const current = $input.first().json;

const previous = current.previous_context ?? current.context ?? {};
const ids = current.ids ?? {};
const payload = current.payload ?? {};

function firstNonNull(...values) {
  return values.find(v => v !== undefined && v !== null && v !== "");
}

return [
  {
    json: {
      status: current.status,
      context: {
        ...previous,
        ...(current.context ?? {}),
        ...Object.fromEntries(
          Object.entries(ids).filter(([_, v]) => v !== null && v !== undefined && v !== "")
        ),
        release_id: firstNonNull(
          current.context?.release_id,
          ids.release_id,
          previous.release_id
        ),
        audit_id: firstNonNull(
          current.context?.audit_id,
          ids.audit_id,
          previous.audit_id
        ),
        trt_id: firstNonNull(
          current.context?.trt_id,
          ids.trt_id,
          payload.plan?.trt_id,
          previous.trt_id
        ),
        trt_version: firstNonNull(
          current.context?.trt_version,
          ids.trt_version,
          payload.plan?.trt_version,
          previous.trt_version
        ),
        reconciliation_plan_id: firstNonNull(
          current.context?.reconciliation_plan_id,
          ids.reconciliation_plan_id,
          payload.plan?.plan_id,
          previous.reconciliation_plan_id
        ),
        scenario_batch_id: firstNonNull(
          current.context?.scenario_batch_id,
          ids.scenario_batch_id,
          previous.scenario_batch_id
        ),
        scenario_spec_ids: firstNonNull(
          current.context?.scenario_spec_ids,
          ids.scenario_spec_ids,
          previous.scenario_spec_ids,
          []
        )
      },
      payload,
      errors: current.errors ?? []
    }
  }
];

